-- eXp Family Tree initial schema.
-- Apply this file to a fresh Supabase project (SQL editor, or `supabase db push`).
-- Do not edit this file after it has been applied. Add a new migration instead.
--
-- Authorization lives in public.profiles.role. Never read roles from auth.users
-- raw_user_meta_data — that JSON is editable by the signed-in user.
-- The private schema must stay out of the Data API "Exposed schemas" list.

create schema if not exists private;

revoke all on schema private from public;
grant usage on schema private to anon, authenticated, service_role, supabase_auth_admin;

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

-- plpgsql so creation does not require public.profiles to exist yet.
create or replace function private.is_admin()
returns boolean
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  return exists (
    select 1
    from public.profiles
    where id = (select auth.uid())
      and role = 'admin'
  );
end;
$$;

create or replace function private.touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create or replace function private.force_member_role()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  -- End users cannot grant themselves admin on insert.
  -- SQL run as the database owner (auth.uid() is null) may set a role.
  if (select auth.uid()) is not null and not private.is_admin() then
    new.role = 'member';
  end if;

  if new.role is null or new.role not in ('member', 'admin') then
    new.role = 'member';
  end if;

  return new;
end;
$$;

create or replace function private.protect_profile()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  auth_email text;
begin
  new.id = old.id;

  select u.email into auth_email
  from auth.users as u
  where u.id = new.id;

  new.email = coalesce(auth_email, old.email);

  if new.role is distinct from old.role
     and (select auth.uid()) is not null
     and not private.is_admin() then
    new.role = old.role;
  end if;

  if new.role is null or new.role not in ('member', 'admin') then
    new.role = old.role;
  end if;

  return new;
end;
$$;

create or replace function private.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  insert into public.profiles (id, email, full_name)
  values (
    new.id,
    coalesce(new.email, ''),
    left(coalesce(new.raw_user_meta_data ->> 'full_name', ''), 120)
  )
  on conflict (id) do nothing;

  insert into public.profile_private (profile_id)
  values (new.id)
  on conflict (profile_id) do nothing;

  return new;
end;
$$;

create or replace function private.sync_profile_email()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  update public.profiles
  set email = coalesce(new.email, '')
  where id = new.id
    and email is distinct from coalesce(new.email, '');

  return new;
end;
$$;

create or replace function private.limit_join_leads()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  new.id = gen_random_uuid();
  new.created_at = now();
  new.status = 'new';

  if (
    select count(*)
    from public.join_leads
    where lower(email) = lower(new.email)
      and created_at > now() - interval '1 day'
  ) >= 3 then
    raise exception 'A request from this email was already saved recently. Try again tomorrow.';
  end if;

  return new;
end;
$$;

revoke all on function private.is_admin() from public;
revoke all on function private.touch_updated_at() from public;
revoke all on function private.force_member_role() from public;
revoke all on function private.protect_profile() from public;
revoke all on function private.handle_new_user() from public;
revoke all on function private.sync_profile_email() from public;
revoke all on function private.limit_join_leads() from public;

grant execute on function private.is_admin() to anon, authenticated, service_role;
grant execute on function private.touch_updated_at() to authenticated, service_role;
grant execute on function private.force_member_role() to authenticated, service_role, supabase_auth_admin;
grant execute on function private.protect_profile() to authenticated, service_role;
grant execute on function private.handle_new_user() to supabase_auth_admin, service_role;
grant execute on function private.sync_profile_email() to supabase_auth_admin, service_role;
grant execute on function private.limit_join_leads() to anon, authenticated, service_role;

-- ---------------------------------------------------------------------------
-- profiles
-- ---------------------------------------------------------------------------

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null default '',
  full_name text not null default '',
  city text not null default '',
  state text not null default '',
  bio text not null default '',
  website text not null default '',
  avatar_path text,
  show_email boolean not null default false,
  directory_visible boolean not null default true,
  role text not null default 'member',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint profiles_role_check check (role in ('member', 'admin')),
  constraint profiles_full_name_len check (char_length(full_name) <= 120),
  constraint profiles_city_len check (char_length(city) <= 80),
  constraint profiles_state_len check (char_length(state) <= 80),
  constraint profiles_bio_len check (char_length(bio) <= 2000),
  constraint profiles_website_len check (char_length(website) <= 300),
  constraint profiles_email_len check (char_length(email) <= 320)
);

comment on table public.profiles is
  'Member profiles. role is the only admin flag. Promote a user from the SQL editor: update public.profiles set role = ''admin'' where email = ''person@example.com'';';

create index profiles_directory_name_idx
  on public.profiles (full_name)
  where directory_visible;

create trigger profiles_force_role
  before insert on public.profiles
  for each row execute function private.force_member_role();

create trigger profiles_protect
  before update on public.profiles
  for each row execute function private.protect_profile();

create trigger profiles_touch_updated_at
  before update on public.profiles
  for each row execute function private.touch_updated_at();

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

create trigger on_auth_user_email_updated
  after update of email on auth.users
  for each row execute function private.sync_profile_email();

alter table public.profiles enable row level security;

revoke all on table public.profiles from public, anon;
grant select, insert, update on table public.profiles to authenticated;
grant select, insert, update, delete on table public.profiles to service_role;

create policy "Members read visible profiles"
  on public.profiles
  for select
  to authenticated
  using (
    id = (select auth.uid())
    or directory_visible = true
    or (select private.is_admin())
  );

create policy "Members insert their own profile"
  on public.profiles
  for insert
  to authenticated
  with check (
    id = (select auth.uid())
    and role = 'member'
  );

create policy "Members update their own profile"
  on public.profiles
  for update
  to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

create policy "Admins update any profile"
  on public.profiles
  for update
  to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

-- Phone numbers are not part of the directory row, so members cannot read
-- them through the public profiles API.
create table public.profile_private (
  profile_id uuid primary key references public.profiles (id) on delete cascade,
  phone text not null default '',
  constraint profile_private_phone_len check (char_length(phone) <= 40)
);

alter table public.profile_private enable row level security;

revoke all on table public.profile_private from public, anon, authenticated;
grant select, insert, update on table public.profile_private to authenticated;
grant select, insert, update, delete on table public.profile_private to service_role;

create policy "Read own private profile"
  on public.profile_private
  for select
  to authenticated
  using (profile_id = (select auth.uid()) or (select private.is_admin()));

create policy "Insert own private profile"
  on public.profile_private
  for insert
  to authenticated
  with check (profile_id = (select auth.uid()));

create policy "Update own private profile"
  on public.profile_private
  for update
  to authenticated
  using (profile_id = (select auth.uid()) or (select private.is_admin()))
  with check (profile_id = (select auth.uid()) or (select private.is_admin()));

-- ---------------------------------------------------------------------------
-- join_leads
-- ---------------------------------------------------------------------------

create table public.join_leads (
  id uuid primary key default gen_random_uuid(),
  full_name text not null,
  email text not null,
  phone text not null default '',
  city text not null default '',
  state text not null default '',
  current_brokerage text not null default '',
  message text not null default '',
  status text not null default 'new',
  created_at timestamptz not null default now(),
  constraint join_leads_status_check check (status in ('new', 'contacted', 'closed')),
  constraint join_leads_name_len check (char_length(full_name) between 1 and 120),
  constraint join_leads_email_len check (char_length(email) between 3 and 320),
  constraint join_leads_email_format check (email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'),
  constraint join_leads_phone_len check (char_length(phone) <= 40),
  constraint join_leads_city_len check (char_length(city) <= 80),
  constraint join_leads_state_len check (char_length(state) <= 80),
  constraint join_leads_brokerage_len check (char_length(current_brokerage) <= 160),
  constraint join_leads_message_len check (char_length(message) <= 4000)
);

comment on table public.join_leads is
  'Interest form submissions from people considering joining eXp through Family Tree. Not member accounts.';

create index join_leads_created_idx on public.join_leads (created_at desc);
create index join_leads_status_idx on public.join_leads (status);
create index join_leads_email_created_idx on public.join_leads (lower(email), created_at desc);

create trigger join_leads_rate_limit
  before insert on public.join_leads
  for each row execute function private.limit_join_leads();

alter table public.join_leads enable row level security;

revoke all on table public.join_leads from public, anon, authenticated;
grant insert on table public.join_leads to anon, authenticated;
grant select, update on table public.join_leads to authenticated;
grant select, insert, update, delete on table public.join_leads to service_role;

create policy "Anyone can submit a join request"
  on public.join_leads
  for insert
  to anon, authenticated
  with check (
    char_length(full_name) between 1 and 120
    and email ~* '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    and status = 'new'
  );

create policy "Admins read join requests"
  on public.join_leads
  for select
  to authenticated
  using ((select private.is_admin()));

create policy "Admins update join requests"
  on public.join_leads
  for update
  to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

-- ---------------------------------------------------------------------------
-- events
-- ---------------------------------------------------------------------------

create table public.events (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text not null default '',
  starts_at timestamptz not null,
  ends_at timestamptz,
  location text not null default '',
  event_type text not null default 'call',
  join_url text not null default '',
  published boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint events_type_check check (event_type in ('call', 'event', 'training')),
  constraint events_title_len check (char_length(title) between 1 and 160),
  constraint events_description_len check (char_length(description) <= 4000),
  constraint events_location_len check (char_length(location) <= 200),
  constraint events_url_len check (char_length(join_url) <= 500),
  constraint events_time_order check (ends_at is null or ends_at >= starts_at)
);

comment on table public.events is
  'Calls, trainings, and gatherings. Published rows are public. Drafts are admin-only.';

create index events_starts_at_idx on public.events (starts_at);
create index events_published_starts_idx on public.events (starts_at) where published;

create trigger events_touch_updated_at
  before update on public.events
  for each row execute function private.touch_updated_at();

alter table public.events enable row level security;

revoke all on table public.events from public, anon, authenticated;
grant select on table public.events to anon, authenticated;
grant insert, update, delete on table public.events to authenticated;
grant select, insert, update, delete on table public.events to service_role;

create policy "Public reads published events"
  on public.events
  for select
  to anon, authenticated
  using (published = true or (select private.is_admin()));

create policy "Admins insert events"
  on public.events
  for insert
  to authenticated
  with check ((select private.is_admin()));

create policy "Admins update events"
  on public.events
  for update
  to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

create policy "Admins delete events"
  on public.events
  for delete
  to authenticated
  using ((select private.is_admin()));

-- ---------------------------------------------------------------------------
-- resources
-- ---------------------------------------------------------------------------

create table public.resources (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  description text not null default '',
  kind text not null,
  url text not null default '',
  storage_path text,
  category text not null default 'General',
  published boolean not null default true,
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint resources_kind_check check (kind in ('link', 'file')),
  constraint resources_title_len check (char_length(title) between 1 and 160),
  constraint resources_description_len check (char_length(description) <= 2000),
  constraint resources_category_len check (char_length(category) between 1 and 80),
  constraint resources_url_len check (char_length(url) <= 500),
  constraint resources_target_check check (
    (kind = 'link' and char_length(url) > 0 and storage_path is null)
    or (kind = 'file' and storage_path is not null)
  )
);

comment on table public.resources is
  'Member library. Links are external URLs. Files live in the resources storage bucket.';

create index resources_published_category_idx
  on public.resources (category, title)
  where published;

create trigger resources_touch_updated_at
  before update on public.resources
  for each row execute function private.touch_updated_at();

alter table public.resources enable row level security;

revoke all on table public.resources from public, anon, authenticated;
grant select, insert, update, delete on table public.resources to authenticated;
grant select, insert, update, delete on table public.resources to service_role;

create policy "Members read published resources"
  on public.resources
  for select
  to authenticated
  using (published = true or (select private.is_admin()));

create policy "Admins insert resources"
  on public.resources
  for insert
  to authenticated
  with check ((select private.is_admin()));

create policy "Admins update resources"
  on public.resources
  for update
  to authenticated
  using ((select private.is_admin()))
  with check ((select private.is_admin()));

create policy "Admins delete resources"
  on public.resources
  for delete
  to authenticated
  using ((select private.is_admin()));

-- ---------------------------------------------------------------------------
-- Storage
-- ---------------------------------------------------------------------------

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values
  (
    'resources',
    'resources',
    false,
    20971520,
    array[
      'application/pdf',
      'application/msword',
      'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      'application/vnd.ms-powerpoint',
      'application/vnd.openxmlformats-officedocument.presentationml.presentation',
      'application/vnd.ms-excel',
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      'text/plain',
      'text/csv',
      'image/jpeg',
      'image/png',
      'image/webp'
    ]
  ),
  (
    'avatars',
    'avatars',
    true,
    5242880,
    array['image/jpeg', 'image/png', 'image/webp']
  )
on conflict (id) do nothing;

create policy "Members read resource files"
  on storage.objects
  for select
  to authenticated
  using (bucket_id = 'resources');

create policy "Admins upload resource files"
  on storage.objects
  for insert
  to authenticated
  with check (bucket_id = 'resources' and (select private.is_admin()));

create policy "Admins update resource files"
  on storage.objects
  for update
  to authenticated
  using (bucket_id = 'resources' and (select private.is_admin()))
  with check (bucket_id = 'resources' and (select private.is_admin()));

create policy "Admins delete resource files"
  on storage.objects
  for delete
  to authenticated
  using (bucket_id = 'resources' and (select private.is_admin()));

create policy "Anyone can view avatars"
  on storage.objects
  for select
  to anon, authenticated
  using (bucket_id = 'avatars');

create policy "Members upload their own avatar"
  on storage.objects
  for insert
  to authenticated
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "Members update their own avatar"
  on storage.objects
  for update
  to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  )
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );

create policy "Members delete their own avatar"
  on storage.objects
  for delete
  to authenticated
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = (select auth.uid())::text
  );
